// Accept either multipart file upload OR a JSON body with { url }.
// Multipart drops the file into binary.file; JSON body lands as $json.body.
const hasBinary = !!$input.first().binary?.file;
const body = $input.first().json.body ?? $input.first().json;
if (hasBinary) {
  const meta = $input.first().binary.file;
  const lower = (meta.fileName || '').toLowerCase();
  let kind = 'txt';
  if (lower.endsWith('.pdf')) kind = 'pdf';
  else if (lower.endsWith('.docx') || lower.endsWith('.doc')) kind = 'docx';
  else if (lower.endsWith('.md')) kind = 'md';
  return [{ json: { mode: 'binary', kind, name: meta.fileName, size: meta.fileSize }, binary: $input.first().binary }];
}
const url = (body.url ?? '').toString().trim();
if (!url) throw new Error('no_file_or_url');
let kind = 'url';
if (/docs\.google\.com\/document/.test(url)) kind = 'gdoc';
return [{ json: { mode: 'url', kind, url, name: url } }];

// DOCX path: use a Code node with mammoth via dynamic import, OR run via
// LibreOffice headless on the n8n host. Below is the mammoth-shaped stub.
const { default: mammoth } = await import('mammoth');
const buffer = Buffer.from($input.first().binary.file.data, 'base64');
const result = await mammoth.extractRawText({ buffer });
return [{ json: { text: result.value } }];

// Strip HTML to plain text + count words + crude language detection.
let raw = $input.first().json.body ?? $input.first().json.text ?? $input.first().json.data ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
// Strip script/style + tags
const stripped = raw
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();
const words = stripped.split(/\s+/).filter(Boolean);
// Naive nl/en detector
const nlMarkers = ['de ','het ','een ','is ','zijn ','niet ','maar ','voor ','wat ','dat ','onderzoek','huidig'];
const lower = stripped.toLowerCase().slice(0, 4000);
const nlHits = nlMarkers.filter(m => lower.includes(m)).length;
const lang = nlHits >= 3 ? 'nl' : 'en';
return [{ json: {
  text: stripped,
  word_count: words.length,
  detected_language: lang,
  source_kind: ($('parse').first().json.kind),
  source_name: ($('parse').first().json.name),
} }];
